{-| @Backend.Runtime.Host.Foreign — the dynamic loader behind native foreign calls: a library opened with the interpreter's candidates in its order, a symbol found once, and E7015 in its words. -}
module Pudu.Backend.Runtime.Host.Foreign (hostForeignParts, foreignLoaderMarker) where

import Data.Text (Text)

{-| The line whose presence in a program's C says the program needs the dynamic loader. -}
foreignLoaderMarker :: Text
foreignLoaderMarker = "#include <dlfcn.h>"

{-| Each part: its name, the parts it needs, and its lines. -}
hostForeignParts :: [(Text, [Text], [Text])]
hostForeignParts =
  [ ("host_foreign", ["fail", "host_math"],
      [ foreignLoaderMarker
      , "#include <pthread.h>"
      , "/* A reference the linker keeps, so the math library stays loaded where the"
      , "   platform links it only when used, and `c` sees the math functions as the"
      , "   interpreter's process does. */"
      , "double (*pudu_foreign_math)(double, double) = pow;"
      , "/* One declaration's resolved function, kept for the life of the program. */"
      , "typedef struct { void (*function)(void); } pudu_foreign_cache;"
      , "static pthread_mutex_t pudu_foreign_lock = PTHREAD_MUTEX_INITIALIZER;"
      , "/* Stops the program at the call with the interpreter's E7015 message. */"
      , "static void pudu_foreign_refuse(const pudu_site *site, const char *symbol, const char *library, const char *release, const char *problem) {"
      , "  char message[4096];"
      , "  int written = snprintf(message, sizeof message, \"cannot call %s in %s: %s%s%s%s\", symbol, library, release == NULL ? \"\" : \"release \", release == NULL ? \"\" : release, release == NULL ? \"\" : \": \", problem);"
      , "  size_t length = written < 0 ? 0 : (size_t)written >= sizeof message ? sizeof message - 1 : (size_t)written;"
      , "  pthread_mutex_unlock(&pudu_foreign_lock);"
      , "  pudu_fail_message(site, message, length);"
      , "}"
      , "/* Appends one candidate file name; the written name comes first, then the"
      , "   versioned spellings, then the plain ones, as the interpreter tries them. */"
      , "static void pudu_foreign_candidate(char names[][512], int *count, const char *prefix, const char *name, const char *middle, const char *version, const char *suffix) {"
      , "  snprintf(names[*count], 512, \"%s%s%s%s%s\", prefix, name, middle, version == NULL ? \"\" : version, suffix);"
      , "  *count += 1;"
      , "}"
      , "static void *pudu_foreign_open(const pudu_site *site, const char *library, const char *version, const char *symbol, const char *producer) {"
      , "  char names[12][512], tried[4096];"
      , "  int count = 0;"
      , "  size_t used = 0;"
      , "  void *handle;"
      , "  if (strcmp(library, \"c\") == 0) {"
      , "    handle = dlopen(NULL, RTLD_LAZY | RTLD_LOCAL);"
      , "    if (handle == NULL) pudu_foreign_refuse(site, producer == NULL ? symbol : producer, library, producer == NULL ? NULL : symbol, \"the program cannot see its own symbols\");"
      , "    return handle;"
      , "  }"
      , "  pudu_foreign_candidate(names, &count, \"\", library, \"\", NULL, \"\");"
      , "  if (version != NULL) {"
      , "    pudu_foreign_candidate(names, &count, \"lib\", library, \".so.\", version, \"\");"
      , "    pudu_foreign_candidate(names, &count, \"lib\", library, \".\", version, \".dylib\");"
      , "    pudu_foreign_candidate(names, &count, \"lib\", library, \"-\", version, \".dll\");"
      , "    pudu_foreign_candidate(names, &count, \"\", library, \".so.\", version, \"\");"
      , "    pudu_foreign_candidate(names, &count, \"\", library, \".\", version, \".dylib\");"
      , "    pudu_foreign_candidate(names, &count, \"\", library, \"-\", version, \".dll\");"
      , "  }"
      , "  pudu_foreign_candidate(names, &count, \"lib\", library, \"\", NULL, \".dylib\");"
      , "  pudu_foreign_candidate(names, &count, \"lib\", library, \"\", NULL, \".so\");"
      , "  pudu_foreign_candidate(names, &count, \"\", library, \"\", NULL, \".dylib\");"
      , "  pudu_foreign_candidate(names, &count, \"\", library, \"\", NULL, \".so\");"
      , "  pudu_foreign_candidate(names, &count, \"\", library, \"\", NULL, \".dll\");"
      , "  for (int i = 0; i < count; ++i) {"
      , "    handle = dlopen(names[i], RTLD_LAZY | RTLD_LOCAL);"
      , "    if (handle != NULL) return handle;"
      , "  }"
      , "  /* The loader's own reason is read before the outermost name reports, so"
      , "     the interpreter's message carries none; this one carries none either. */"
      , "  (void)dlerror();"
      , "  used = (size_t)snprintf(tried, sizeof tried, \"could not open the library; tried \");"
      , "  for (int i = 0; i < count && used < sizeof tried; ++i)"
      , "    used += (size_t)snprintf(tried + used, sizeof tried - used, \"%s%s\", i == 0 ? \"\" : \", \", names[i]);"
      , "  pudu_foreign_refuse(site, producer == NULL ? symbol : producer, library, producer == NULL ? NULL : symbol, tried);"
      , "  return NULL;"
      , "}"
      , "/* The function a declaration calls, resolved on its first call. */"
      , "static void (*pudu_foreign_function(const pudu_site *site, pudu_foreign_cache *cache, const char *library, const char *version, const char *symbol, const char *producer))(void) {"
      , "  void (*function)(void);"
      , "  pthread_mutex_lock(&pudu_foreign_lock);"
      , "  if (cache->function == NULL) {"
      , "    void *handle = pudu_foreign_open(site, library, version, symbol, producer);"
      , "    void *address = dlsym(handle, symbol);"
      , "    if (address == NULL) {"
      , "      char problem[600];"
      , "      snprintf(problem, sizeof problem, \"the library exports no %s\", symbol);"
      , "      pudu_foreign_refuse(site, producer == NULL ? symbol : producer, library, producer == NULL ? NULL : symbol, problem);"
      , "    }"
      , "    memcpy(&cache->function, &address, sizeof cache->function);"
      , "  }"
      , "  function = cache->function;"
      , "  pthread_mutex_unlock(&pudu_foreign_lock);"
      , "  return function;"
      , "}"
      ])
  , ("host_foreign_text_in", ["host_optional", "fail", "memory_failure"],
      [ "PUDU_OPTIONAL static void pudu_foreign_text_check(const pudu_site *noughts, pudu_text text) {"
      , "  if (text.length != 0 && memchr(text.bytes, 0, text.length) != NULL) pudu_fail(noughts);"
      , "}"
      , "/* The validated text is copied with a closing nought for the call. */"
      , "PUDU_OPTIONAL static char *pudu_foreign_text_in(pudu_text text) {"
      , "  char *copy;"
      , "  copy = malloc(text.length + 1);"
      , "  if (copy == NULL) pudu_memory_failure();"
      , "  if (text.length != 0) memcpy(copy, text.bytes, text.length);"
      , "  copy[text.length] = 0;"
      , "  return copy;"
      , "}"
      ])
  , ("host_foreign_text_out", ["host_optional", "fail", "text_copy", "utf8_valid"],
      [ "/* Validate before copying, so a refusal can release the call's arguments. */"
      , "PUDU_OPTIONAL static int pudu_foreign_text_valid(const char *answer) {"
      , "  return pudu_utf8_valid((const unsigned char *)answer, strlen(answer));"
      , "}"
      , "PUDU_OPTIONAL static void pudu_foreign_missing_field(const pudu_site *missing, const char *symbol, const char *label) {"
      , "  char message[600];"
      , "  int written = snprintf(message, sizeof message, \"%s returned no text for %s\", symbol, label);"
      , "  pudu_fail_message(missing, message, written < 0 ? 0 : (size_t)written >= sizeof message ? sizeof message - 1 : (size_t)written);"
      , "}"
      ])
  , ("host_foreign_bytes", [],
      [ "/* A run of bytes lent for the call; an empty run is still an address. */"
      , "static const void *pudu_foreign_bytes_in(pudu_box *box) {"
      , "  static const unsigned char none = 0;"
      , "  return box->fields[0].text.bytes != NULL ? (const void *)box->fields[0].text.bytes : (const void *)&none;"
      , "}"
      ])
  , ("host_foreign_store", ["host_optional", "host_foreign", "fail", "memory_failure"],
      [ "/* The run gate covers foreign dispatch and claim settlement. No foreign"
      , "   wrapper yields it, including while explicitly releasing a handle. */"
      , "typedef struct {"
      , "  uint64_t address, generation;"
      , "  int counted;"
      , "  void (*release)(uint64_t);"
      , "} pudu_foreign_claim;"
      , "static pudu_foreign_claim *pudu_foreign_claims = NULL;"
      , "static size_t pudu_foreign_claim_count = 0, pudu_foreign_claim_room = 0;"
      , "static uint64_t pudu_foreign_next_generation = 1;"
      , "static int pudu_foreign_claim_order(const void *a, const void *b) {"
      , "  const pudu_foreign_claim *p = a, *q = b;"
      , "  if (p->counted != q->counted) return p->counted - q->counted;"
      , "  if (!p->counted && p->address != q->address)"
      , "    return (p->address ^ (UINT64_C(1) << 63)) < (q->address ^ (UINT64_C(1) << 63)) ? -1 : 1;"
      , "  return p->generation < q->generation ? -1 : p->generation > q->generation;"
      , "}"
      , "static void pudu_foreign_teardown(void) {"
      , "  pudu_foreign_claim *held = pudu_foreign_claims;"
      , "  size_t count = pudu_foreign_claim_count;"
      , "  pudu_foreign_claims = NULL;"
      , "  pudu_foreign_claim_count = pudu_foreign_claim_room = 0;"
      , "  if (count != 0) qsort(held, count, sizeof *held, pudu_foreign_claim_order);"
      , "  for (size_t i = 0; i < count; ++i) held[i].release(held[i].address);"
      , "  free(held);"
      , "}"
      , "/* Reserve before the producer can hand back a resource. */"
      , "PUDU_OPTIONAL static void pudu_foreign_reserve(size_t count) {"
      , "  if (pudu_foreign_next_generation == 0 || count - 1 > UINT64_MAX - pudu_foreign_next_generation) pudu_memory_failure();"
      , "  if (count > pudu_foreign_claim_room - pudu_foreign_claim_count) {"
      , "    size_t room = pudu_foreign_claim_room;"
      , "    pudu_foreign_claim *grown;"
      , "    if (count > SIZE_MAX / sizeof *grown - pudu_foreign_claim_count) pudu_memory_failure();"
      , "    room = room == 0 ? 8 : room;"
      , "    while (count > room - pudu_foreign_claim_count) { if (room > SIZE_MAX / sizeof *grown / 2) pudu_memory_failure(); room *= 2; }"
      , "    grown = pudu_foreign_claims == NULL ? malloc(room * sizeof *grown) : realloc(pudu_foreign_claims, room * sizeof *grown);"
      , "    if (grown == NULL) pudu_memory_failure();"
      , "    pudu_foreign_claims = grown;"
      , "    pudu_foreign_claim_room = room;"
      , "  }"
      , "}"
      , "PUDU_OPTIONAL static int pudu_foreign_address_held(uint64_t address) {"
      , "  for (size_t i = 0; i < pudu_foreign_claim_count; ++i)"
      , "    if (!pudu_foreign_claims[i].counted && pudu_foreign_claims[i].address == address) return 1;"
      , "  return 0;"
      , "}"
      , "PUDU_OPTIONAL static void pudu_foreign_claim_slots(const pudu_site *duplicate, pudu_foreign_claim *slots, size_t count) {"
      , "  int refused = 0;"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    if (slots[i].address == 0) continue;"
      , "    if (pudu_foreign_address_held(slots[i].address)) refused = 1;"
      , "    for (size_t j = 0; j < i; ++j) if (slots[i].address == slots[j].address) refused = 1;"
      , "  }"
      , "  if (refused) {"
      , "    qsort(slots, count, sizeof *slots, pudu_foreign_claim_order);"
      , "    for (size_t i = 0; i < count;) {"
      , "      uint64_t address = slots[i].address;"
      , "      size_t end = i + 1;"
      , "      int agrees = 1;"
      , "      while (end < count && slots[end].address == address) {"
      , "        if (slots[end].release != slots[i].release || slots[end].generation != slots[i].generation) agrees = 0;"
      , "        ++end;"
      , "      }"
      , "      if (address != 0 && agrees && !pudu_foreign_address_held(address)) slots[i].release(address);"
      , "      i = end;"
      , "    }"
      , "    pudu_fail(duplicate);"
      , "    return;"
      , "  }"
      , "  for (size_t i = 0; i < count; ++i) if (slots[i].address != 0) {"
      , "    slots[i].generation = pudu_foreign_next_generation++;"
      , "    pudu_foreign_claims[pudu_foreign_claim_count++] = slots[i];"
      , "  }"
      , "}"
      , "PUDU_OPTIONAL static pudu_box *pudu_foreign_slot_box(uint64_t address, uint64_t generation) {"
      , "  pudu_box *made = pudu_box_new(2);"
      , "  made->fields[0].floating = address;"
      , "  made->fields[1].floating = generation;"
      , "  return made;"
      , "}"
      , "PUDU_OPTIONAL static pudu_box *pudu_foreign_handle_result(const pudu_site *none, const pudu_site *owned, int mode,"
      , "    void (*release)(uint64_t), void *answer) {"
      , "  uint64_t address = (uint64_t)(uintptr_t)answer, generation = 0;"
      , "  if (answer == NULL) pudu_fail(none);"
      , "  if (mode == 1)"
      , "    for (size_t i = 0; i < pudu_foreign_claim_count; ++i)"
      , "      if (!pudu_foreign_claims[i].counted && pudu_foreign_claims[i].address == address) pudu_fail(owned);"
      , "  if (mode != 0) {"
      , "    generation = pudu_foreign_next_generation++;"
      , "    pudu_foreign_claims[pudu_foreign_claim_count++] = (pudu_foreign_claim){address, generation, mode == 2, release};"
      , "  }"
      , "  return pudu_foreign_slot_box(address, generation);"
      , "}"
      , "PUDU_OPTIONAL static void pudu_foreign_require(const pudu_site *dead, pudu_box *handle, int take) {"
      , "  uint64_t generation = handle->fields[1].floating;"
      , "  if (generation == 0 && !take) return;"
      , "  for (size_t i = 0; i < pudu_foreign_claim_count; ++i)"
      , "    if (pudu_foreign_claims[i].generation == generation) {"
      , "      if (take) pudu_foreign_claims[i] = pudu_foreign_claims[--pudu_foreign_claim_count];"
      , "      return;"
      , "    }"
      , "  pudu_fail(dead);"
      , "}"
      ])
  ]
